mapper.select:
SELECT id, revision, state, package_key, plan_sha256, create_copy, import_count, skip_count, created_at, committed_at
FROM knowledge_package WHERE owner_id=#{owner}

  AND (created_at < #{cursorTime} OR (created_at=#{cursorTime} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC LIMIT #{limit}
